public static void check(Solution solution) {
    assert Arrays.equals(solution.stringIndices(new int[]{"banana","mango","papaya"}, new int[]{"ana","ango","aya"}), new int[]{0, 1, 2});
    assert Arrays.equals(solution.stringIndices(new int[]{"abcde","bcde","cde","de","e"}, new int[]{"cde","de","e","a","b"}), new int[]{2, 3, 4, 4, 4});
    assert Arrays.equals(solution.stringIndices(new int[]{"xyz","zyx","zxy"}, new int[]{"x","y","z"}), new int[]{1, 2, 0});
    assert Arrays.equals(solution.stringIndices(new int[]{"zzzzz","zzzz","zzz","zz","z"}, new int[]{"zzzz","zzz","zz","z","a"}), new int[]{1, 2, 3, 4, 4});
    assert Arrays.equals(solution.stringIndices(new int[]{"a","ab","abc"}, new int[]{"a","ab","abc"}), new int[]{0, 1, 2});
    assert Arrays.equals(solution.stringIndices(new int[]{"unique","suffix","words"}, new int[]{"fix","ffix","uffix"}), new int[]{1, 1, 1});
    assert Arrays.equals(solution.stringIndices(new int[]{"abcd","bcd","xbcd"}, new int[]{"cd","bcd","xyz"}), new int[]{1, 1, 1});
    assert Arrays.equals(solution.stringIndices(new int[]{"hello","world","python"}, new int[]{"lo","rld","on"}), new int[]{0, 1, 2});
    assert Arrays.equals(solution.stringIndices(new int[]{"a","b","c"}, new int[]{"d","e","f"}), new int[]{0, 0, 0});
    assert Arrays.equals(solution.stringIndices(new int[]{"abcdefgh","poiuygh","ghghgh"}, new int[]{"gh","acbfgh","acbfegh"}), new int[]{2, 0, 2});
    assert Arrays.equals(solution.stringIndices(new int[]{"abcde","bcde","cde"}, new int[]{"cde","de","e"}), new int[]{2, 2, 2});
    assert Arrays.equals(solution.stringIndices(new int[]{"same","same","same"}, new int[]{"same","same","same"}), new int[]{0, 0, 0});
    assert Arrays.equals(solution.stringIndices(new int[]{"longestword","short","word"}, new int[]{"word","short","longestword"}), new int[]{2, 1, 0});
    assert Arrays.equals(solution.stringIndices(new int[]{"apple","maple","orange"}, new int[]{"le","ple","range"}), new int[]{0, 0, 2});
    assert Arrays.equals(solution.stringIndices(new int[]{"a","b","c"}, new int[]{"a","b","c"}), new int[]{0, 1, 2});
    assert Arrays.equals(solution.stringIndices(new int[]{"abc","def","ghi"}, new int[]{"abc","def","ghi"}), new int[]{0, 1, 2});
