function check(candidate) {
    console.assert(JSON.stringify(candidate(["banana","mango","papaya"], ["ana","ango","aya"])) === JSON.stringify([0, 1, 2]));
    console.assert(JSON.stringify(candidate(["abcde","bcde","cde","de","e"], ["cde","de","e","a","b"])) === JSON.stringify([2, 3, 4, 4, 4]));
    console.assert(JSON.stringify(candidate(["xyz","zyx","zxy"], ["x","y","z"])) === JSON.stringify([1, 2, 0]));
    console.assert(JSON.stringify(candidate(["zzzzz","zzzz","zzz","zz","z"], ["zzzz","zzz","zz","z","a"])) === JSON.stringify([1, 2, 3, 4, 4]));
    console.assert(JSON.stringify(candidate(["a","ab","abc"], ["a","ab","abc"])) === JSON.stringify([0, 1, 2]));
    console.assert(JSON.stringify(candidate(["unique","suffix","words"], ["fix","ffix","uffix"])) === JSON.stringify([1, 1, 1]));
    console.assert(JSON.stringify(candidate(["abcd","bcd","xbcd"], ["cd","bcd","xyz"])) === JSON.stringify([1, 1, 1]));
    console.assert(JSON.stringify(candidate(["hello","world","python"], ["lo","rld","on"])) === JSON.stringify([0, 1, 2]));
    console.assert(JSON.stringify(candidate(["a","b","c"], ["d","e","f"])) === JSON.stringify([0, 0, 0]));
    console.assert(JSON.stringify(candidate(["abcdefgh","poiuygh","ghghgh"], ["gh","acbfgh","acbfegh"])) === JSON.stringify([2, 0, 2]));
    console.assert(JSON.stringify(candidate(["abcde","bcde","cde"], ["cde","de","e"])) === JSON.stringify([2, 2, 2]));
    console.assert(JSON.stringify(candidate(["same","same","same"], ["same","same","same"])) === JSON.stringify([0, 0, 0]));
    console.assert(JSON.stringify(candidate(["longestword","short","word"], ["word","short","longestword"])) === JSON.stringify([2, 1, 0]));
    console.assert(JSON.stringify(candidate(["apple","maple","orange"], ["le","ple","range"])) === JSON.stringify([0, 0, 2]));
    console.assert(JSON.stringify(candidate(["a","b","c"], ["a","b","c"])) === JSON.stringify([0, 1, 2]));
    console.assert(JSON.stringify(candidate(["abc","def","ghi"], ["abc","def","ghi"])) === JSON.stringify([0, 1, 2]));
    console.assert(JSON.stringify(candidate(["a","b","c","d"], ["a","b","c","d"])) === JSON.stringify([0, 1, 2, 3]));
    console.assert(JSON.stringify(candidate(["qwerty","werty","erty","rty","ty","y"], ["y","ty","rty","erty","werty","qwerty","ertyu","qwertyu"])) === JSON.stringify(Error: ord() expected a character, but string of length 7 found));
    console.assert(JSON.stringify(candidate(["aaaaa","bbbbb","ccccc","abcde","bcdef","cdefg"], ["abcde","bcdef","cdefg","de","ef","f"])) === JSON.stringify([3, 4, 5, 3, 4, 4]));
    console.assert(JSON.stringify(candidate(["abcdef","defabc","abc","def","efg","fg","g"], ["abc","def","efg","fg","g","a","bcd","cde"])) === JSON.stringify([2, 3, 4, 5, 6, 6, 6, 6]));
